// Hero of /booking: the offer on the left on a warm light background, a clinic photo
// on the right in a rounded 3:2 frame with a fill accent; on phones the photo sits under the text.
import { srcSetOf, useFitWords } from "@wizard/ui-kit/v3/headless";
import { domAnimation, LazyMotion, m, useReducedMotion } from "motion/react";
import { useState } from "react";

export type BookingHeroProps = {
  heading: string;
  text: string;
  button: string;
  buttonHref: string;
  photo: { src: string; alt: string };
  wzId?: string;
};

/** Entrance of the first screen (rise, calm profile only, never with reduced motion). */
function useEnter() {
  const reduce = useReducedMotion();
  const [lively] = useState(
    () =>
      typeof document !== "undefined" &&
      getComputedStyle(document.documentElement).getPropertyValue("--ds-motion").trim() === "lively",
  );
  const on = lively && !reduce;
  return (step: number) =>
    on
      ? {
          initial: { opacity: 0, y: 16 },
          animate: { opacity: 1, y: 0 },
          transition: { duration: 0.6, delay: step * 0.08, ease: [0.23, 1, 0.32, 1] as const },
        }
      : {};
}

export default function BookingHero({ heading, text, button, buttonHref, photo, wzId }: BookingHeroProps) {
  const enter = useEnter();
  const fit = useFitWords<HTMLHeadingElement>(heading);

  return (
    <LazyMotion features={domAnimation}>
      <section data-wz-component="Hero" data-wz-id={wzId} className="bg-background font-sans text-foreground">
        <div className="mx-auto grid w-full max-w-page items-center gap-10 px-gutter py-section lg:grid-cols-12 lg:gap-16">
          <div className="order-1 min-w-0 lg:col-span-7">
            <m.h1
              ref={fit}
              {...enter(0)}
              className="font-display text-hero font-bold text-balance wrap-break-word hyphens-auto"
            >
              {heading}
            </m.h1>
            <m.p {...enter(1)} className="mt-6 max-w-text text-lead text-muted-foreground">
              {text}
            </m.p>
            <m.div {...enter(2)} className="mt-9">
              <a
                href={buttonHref}
                data-testid="wz-hero-primary"
                className="inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary px-8 text-center text-body font-bold text-primary-foreground transition-transform duration-200 hover:-translate-y-0.5 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
              >
                {button}
              </a>
            </m.div>
          </div>
          <m.div {...enter(1)} className="order-2 min-w-0 lg:col-span-5">
            <img
              src={photo.src}
              srcSet={srcSetOf(photo.src)}
              sizes="(min-width: 1024px) 42vw, 100vw"
              alt={photo.alt}
              fetchPriority="high"
              className="aspect-3/2 w-full rounded-lg bg-muted object-cover"
            />
          </m.div>
        </div>
      </section>
    </LazyMotion>
  );
}

