// Steps «booking ribbon»: an airy horizontal band after the dense form — the heading left,
// three steps flow as a ribbon of wide blocks where the step number is drawn by the code
// (large tabular figure set on the baseline with the title, not written in text) and a thin
// rule runs along the top edge of each block so the steps read as one continuous strip.
// On phones the ribbon stacks into a column. Own composition, calm rise entrance.

type Step = { title: string; text?: string };

export type BookingStepsProps = {
  heading: string;
  steps: Step[];
};

import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

export default function BookingSteps({ heading, steps }: BookingStepsProps) {
  const reduced = useReducedMotion();

  return (
    <section className="bg-background font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <m.div
          initial={reduced ? undefined : { opacity: 0, y: 24 }}
          whileInView={reduced ? undefined : { opacity: 1, y: 0 }}
          viewport={{ once: true, margin: "-80px" }}
          transition={{ duration: 0.6, ease: "easeOut" }}
        >
          <h2 className="font-display text-h1 font-bold text-balance wrap-break-word">{heading}</h2>
        </m.div>

        <ol className="mt-14 grid gap-x-10 gap-y-12 sm:grid-cols-2 lg:grid-cols-3">
          {steps.map((step, i) => (
            <m.li
              key={step.title}
              initial={reduced ? undefined : { opacity: 0, y: 24 }}
              whileInView={reduced ? undefined : { opacity: 1, y: 0 }}
              viewport={{ once: true, margin: "-80px" }}
              transition={{ duration: 0.6, delay: i * 0.12, ease: "easeOut" }}
              className="relative border-t-2 border-border pt-6 min-w-0"
            >
              <span
                aria-hidden="true"
                className="absolute -top-[2px] left-0 h-[2px] w-12 bg-primary"
              />
              <div className="flex items-baseline gap-3">
                <span
                  aria-hidden="true"
                  className="shrink-0 font-display text-h2 font-bold tabular-nums text-muted-foreground"
                >
                  {String(i + 1).padStart(2, "0")}
                </span>
                <h3 className="font-display text-h3 font-bold text-balance wrap-break-word">
                  {step.title}
                </h3>
              </div>
              {step.text ? (
                <p className="mt-3 pl-0 text-body text-pretty text-muted-foreground sm:pl-[3.25rem]">
                  {step.text}
                </p>
              ) : null}
            </m.li>
          ))}
        </ol>
      </div>
    </section>
  );
}

