import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

export type CabinetSectionProps = {
  heading: string;
  text: string;
  link: string;
  linkHref: string;
};

export default function CabinetSection({ heading, text, link, linkHref }: CabinetSectionProps) {
