          <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">{heading}</h2>
          <p className="mt-4 max-w-text text-lead text-pretty text-muted-foreground">{text}</p>
          <a
            href={linkHref}
            className="mt-8 inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary px-6 text-center text-body font-bold text-primary-foreground transition-transform duration-200 hover:-translate-y-0.5 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
          >
            {link}
          </a>
        </m.div>
      </LazyMotion>
    </section>
  );
}

